// AccessLevel The caller's access (P0-16, PRD §7): `trial` (running trial, capped records), `pro` (store plan), `comp` (granted), `read_only` (trial over and no plan: reads, deletes and restores stay, creates and edits answer `402`).
type AccessLevel string

// AccessSummary The caller's access state, computed by the server so the client never uses its own clock (OQ-D6). Per user, across all taxpayers (PRD Q2). One shape for every screen that needs it: the Home banner (`getDashboard`), the subscription status (M7) and the check before a create wizard (MODULES.md M7, PR #58 follow-up: M7-01 exposes this same schema to the app regardless of `module_subscriptions`). `trial`: `trial_ends_at` (exclusive), `trial_days_left` (whole days left, rounded up, at least 1 while the trial runs) and the records left of each kind. `read_only`: both counters `0`, the trial fields `null`. `pro`, `comp`: every other field `null` (no limit applies).
//
// Examples: {"access":"trial","expenses_remaining":5,"incomes_remaining":2,"trial_days_left":3,"trial_ends_at":"2026-10-20T16:00:00Z"}
type AccessSummary struct {
	// Access The caller's access (P0-16, PRD §7): `trial` (running trial, capped records), `pro` (store plan), `comp` (granted), `read_only` (trial over and no plan: reads, deletes and restores stay, creates and edits answer `402`).
	Access            AccessLevel `json:"access"`
	ExpensesRemaining *int        `json:"expenses_remaining"`
	IncomesRemaining  *int        `json:"incomes_remaining"`
	TrialDaysLeft     *int        `json:"trial_days_left"`
	TrialEndsAt       *time.Time  `json:"trial_ends_at"`
}

// AnnualBalance `isr_cents − credits.total_cents`, rounded once to the centavo (half away from zero): positive → `a_cargo`, negative → `a_favor` with its absolute value, zero → `cero`.
